export function IconWrapper(name: any, spin: any, render: any): {
    name: string;
    props: {
        size: {
            type: (StringConstructor | NumberConstructor)[];
            default: string;
        };
        color: {
            type: StringConstructor;
            default: string;
        };
        rotate: {
            type: NumberConstructor;
        };
        spin: {
            type: BooleanConstructor;
            default: any;
        };
        grayscale: {
            type: BooleanConstructor;
            default: boolean;
        };
    };
    setup(props: any): () => any;
};
